import type { LessonData, DialogueLine } from "./lessons";
import type { RolePlayScenario } from "./industry-course-builder";

type ScenarioSeed = Omit<RolePlayScenario, "model"> & { model: DialogueLine[] };

const scenario = (
  title: string,
  situation: string,
  roles: string[],
  goal: string,
  steps: string[],
  usefulPhrases: string[],
  model: DialogueLine[],
): ScenarioSeed => ({ title, situation, roles, goal, steps, usefulPhrases, model });

