const courseSets: Record<string, { label: string; scenarios: ScenarioSeed[] }> = {
  "customer-service": { label: "Customer Service English — A2–B1", scenarios: customerService },
  hospitality: { label: "Hospitality English — A2–B1", scenarios: hospitality },
  healthcare: { label: "English for Healthcare — B1–B2", scenarios: healthcare },
  "it-english": { label: "IT English — B1–C1", scenarios: itSupport },
};

export function applyIndustryRolePlays(lessonMap: Record<string, LessonData>): void {
  Object.entries(courseSets).forEach(([courseId, course]) => {
    course.scenarios.forEach((rolePlay, index) => {
      const lesson = lessonMap[`${courseId}-${index + 1}`];
      if (!lesson) return;
      lesson.levelLabel = course.label;
      lesson.rolePlay = [rolePlay];
    });
  });
}
